INSERT INTO m223_art VALUES
(0,0,$m223$الديباجة$m223$,$m223$الجريدة الرسمية - العدد 45 مكرر (أ) في 13 نوفمبر سنة 2013
قرار رئيس جمهورية مصر العربية
بالقانون رقم 106 لسنة 2013
فى شأن حظر تعارض مصالح المسئولين فى الدولة
رئيس الجمهورية المؤقت
بعد الاطلاع على الإعلان الدستورى الصادر فى الثامن من يوليو 2013 ؛
وعلى قانون العقوبات الصادر بالقانون رقم 58 لسنة 1937 ؛
وعلى القانون رقم 62 لسنة 1975 بشأن الكسب غير المشروع ؛
وعلى قانون نظام العاملين المدنيين بالدولة الصادر بالقانون رقم 47 لسنة 1978 ؛
وعلى قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 ؛
وعلى قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998 ؛
وعلى قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 ؛
وعلى قرار رئيس الجمهورية رقم 307 لسنة 2004 بشأن انضمام حكومة جمهورية مصر العربية لاتفاقية الأمم المتحدة لمكافحة الفساد الموقعة بتاريخ 2003/12/9 ؛
وبعد أخذ رأى مجلس الوزراء ؛
وبناءً على ما ارتآه مجلس الدولة ؛
قــــــرر :
القانون الآتى نصه :$m223$,'68dd433982c04d1def554aad72fd5db5',DATE '2013-12-14'),
(1,0,$m223$المادة (1)$m223$,$m223$يخضع لأحكام هذا القانون كل من :
( أ ) رئيس الجمهورية .
(ب) رئيس مجلس الوزراء والوزراء .
(ج) المحافظين وسكرتيرى عموم المحافظات ورؤساء الوحدات المحلية .
(د) رؤساء الهيئات والمؤسسات والمصالح والأجهزة العامة .
(هـ) نواب ومساعدى الأشخاص شاغلى المناصب والوظائف المشار إليهم فى البنود السابقة ، ومن يفوضونهم فى بعض اختصاصاتهم .$m223$,'9ada091712c1699ce7aadd7868f94735',DATE '2013-12-14'),
(2,0,$m223$المادة (2)$m223$,$m223$فى تطبيق أحكام هذا القانون يقصد بالكلمات والعبارات الآتية المعانى المبينة قرين كل منها :
1 - المسئول الحكومى : كل شخص يشغل أحد المناصب أو الوظائف المنصوص عليها بالمادة الأولى من هذا القانون .
2 - الشخص المرتبط : كل شخص تربطه بالمسئول الحكومى صلة قرابة حتى الدرجة الرابعة ، والشركات التى يساهمون فيها أو يديرونها .
3 - تعارض المصالح : كل حالة يكون للمسئول الحكومى أو الشخص المرتبط به مصلحة مادية أو معنوية تتعارض تعارضًا مطلقًا أو نسبيًا مع ما يتطلبه منصبه أو وظيفته من نزاهة واستقلال وحفاظ على المال العام أو تكون سببًا لكسب غير مشروع لنفسه أو للشخص المرتبط .
4 - التعارض المطلق : كل حالة يترتب عليها ضرر مباشر أو محقق للمصلحة أو الوظيفة العامة .
5 - التعارض النسبى : كل حالة يحتمل فيها وقوع ضرر للمصلحة أو الوظيفة العامة .$m223$,'67c898c499f076698b6a077e8bedefa0',DATE '2013-12-14'),
(3,0,$m223$المادة (3)$m223$,$m223$فى حالة قيام إحدى حالات التعارض المطلق يتعين على المسئول الحكومى إزالة هذا التعارض إما بالتنازل عن المصلحة أو ترك المنصب أو الوظيفة العامة ، فإذا كان التعارض نسبيًا تعين على المسئول الحكومى الإفصاح عن هذا التعارض واتخاذ الإجراءات اللازمة للحيلولة دون وقوع ضرر للمصلحة العامة ، وفقًا للإجراءات والضوابط المبينة فى هذا القانون .$m223$,'3583d221b7890fe4d20cd891eb422f05',DATE '2013-12-14'),
(4,0,$m223$المادة (4)$m223$,$m223$تنشأ لجنة تسمى « لجنة الوقاية من الفساد » يعهد إليها بتطبيق أحكام هذا القانون بما فى ذلك تقدير ما يعد تعارضًا مطلقًا أو تعارضًا نسبيًا ، ويصدر بتشكيلها وتحديد اختصاصاتها قرار من رئيس الجمهورية .$m223$,'b474a011f6a89761bae93f81276ff4f5',DATE '2013-12-14'),
(5,0,$m223$المادة (5)$m223$,$m223$مع عدم الإخلال بأحكام قانون الكسب غير المشروع المُشار إليه ، على المسئول الحكومى خلال شهر من تعيينه تقديم صورة من إقرار ذمته المالية ، وتحديثه سنويًا ، إلى لجنة الوقاية من الفساد .$m223$,'35c60117a38a2e503b3edc81c946c051',DATE '2013-12-14'),
(6,0,$m223$المادة (6)$m223$,$m223$يُعد الجمع بين عمل المسئول الحكومى وبين عضوية مجالس إدارة الشركات أو المشروعات التجارية الخاصة أو العمل فيها تعارضًا مطلقًا ، ويتعين عليه الاستقالة من تلك العضوية أو العمل فور تعيينه فى المنصب أو الوظيفة العامة ، فإذا لزم اتخاذ إجراءات معينة لقبول الاستقالة ، وجب عليه خلال الفترة اللازمة لذلك أن يمتنع عن حضور المجلس أو المشاركة فى أنشطة المشروع أو الشركة أو فى اتخاذ القرارات الخاصة بها ، وعن قبول أى عائد مادى منها .$m223$,'8059a4aee9ae46864bf7fb90a639f0bc',DATE '2013-12-14'),
(7,0,$m223$المادة (7)$m223$,$m223$على المسئول الحكومى فور تعيينه فى منصبه أو وظيفته أن يتخذ الإجراءات اللازمة لفصل ملكيته فى أسهم أو حصص الشركات أو المشروعات التجارية عن إدارة أى أسهم أو حصص فى هذه الشركات أو المشروعات أو فى أى أشكال أخرى للمشاركة فى أرباحها ، وذلك خلال مدة لا تجاوز شهرين من تعيينه ، ووفقًا للضوابط والإجراءات المنصوص عليها فى المادة (8) من هذا القانون ، وإلا تعين عليه التصرف فى تلك الأسهم أو الحصص خلال المدة ذاتها طبقًا لقواعد تحديد السعر العادل المنصوص عليها فى المادة (12) من هذا القانون .
ويكون التعارض مطلقًا إذا كانت ملكية الأسهم والحصص فى شركات خاضعة لرقابة المسئول الحكومى أو تابعة له بشكل مباشر أو غير مباشر ، وفى هذه الحالة يتعين عليه التصرف فى ملكيته خلال مدة الشهرين المُشار إليهما أو ترك المنصب أو الوظيفة العامة .
ولا تُعتبر ملكية العقارات من الأنشطة التجارية التى تسرى عليها أحكام هذه المادة ولو كانت مؤجرة أو مزروعة ، ما لم يتخذ التعامل فيها شكل الاتجار على وجه الاعتياد .$m223$,'783957d5e2a977d68b8b3cdf3cd17552',DATE '2013-12-14'),
(8,0,$m223$المادة (8)$m223$,$m223$يكون فصل ملكية الأسهم والحصص عن إدارتها عن طريق قيام المسئول الحكومى بإبرام عقد لإدارة هذه الأصول مع شخص طبيعى أو اعتبارى مستقل من غير الأشخاص المرتبطين به ، ومن غير شركائه فى النشاط التجارى ، وامتناعه عن التدخل فى قرارات إدارة تلك الأصول إلا ما تعلق منها بالموافقة على التصرف بالبيع أو التنازل .
ويصدر قرار من مجلس الوزراء بإجراءات وضوابط تطبيق الفقرة السابقة بناءً على اقتراح لجنة الوقاية من الفساد .
وعلى المسئول الحكومى أن يخطر لجنة الوقاية من الفساد بالأسهم والحصص التى عهد بإدارتها إلى الغير وفقًا لأحكام هذه المادة وبيانات من عهد إليه بالإدارة وصلاحياته ، وأن يقدم إليها تقريرًا سنويًا عن نتائج أعمال تلك الإدارة .$m223$,'5dfd998ad94c5a4a5c452502541a8cd3',DATE '2013-12-14'),
(9,0,$m223$المادة (9)$m223$,$m223$لا يجوز للمسئول الحكومى طوال فترة شغله لمنصبه أو وظيفته أن يشترى بشكل مباشر أو غير مباشر أسهمًا أو حصصًا فى شركات أو مشروعات تجارية أو زيادة حصته فيها إلا فى الحالتين الآتيتين :
( أ ) المشاركة فى زيادة رأس مال مشروع يساهم فيه قبل تولى المنصب على أن تكون الزيادة مطروحة لكافة الشركاء وأن يشارك فيها بما يحفظ نسبته من النقصان دون زيادتها .
( ب) الاكتتاب فى صناديق استثمار مصرية مطروحة للاكتتاب العام .
وفى جميع الأحوال يكون الشراء بالسعر العادل على النحو المبين فى المادة (12) من هذا القانون .$m223$,'19754245881b56a3d9c63e9a5711acc2',DATE '2013-12-14'),
(10,0,$m223$المادة (10)$m223$,$m223$على المسئول الحكومى الذى يزاول نشاطًا مهنيًا بمفرده أو بالمشاركة مع الغير قبل تعيينه فى منصبه أو وظيفته أن يتخذ فور تعيينه الإجراءات اللازمة لوقف أو تصفية نشاطه أو للتصرف فى حصته فى النشاط خلال شهرين من تعيينه .$m223$,'f31a36caa27df9d579822c423e2f5c2d',DATE '2013-12-14'),
(11,0,$m223$المادة (11)$m223$,$m223$يحظر على المسئول الحكومى تقديم الخدمات الاستشارية ، سواء مدفوعة الأجر أو غير مدفوعة .$m223$,'45d120504a5dfb54422b43d6e1626dbf',DATE '2013-12-14'),
(12,0,$m223$المادة (12)$m223$,$m223$مع عدم الإخلال بالنصوص التى تحظر أو تنظم تعاملات المسئولين الحكوميين بشأن الأموال والأصول المملوكة للدولة ، يكون كل تعامل للمسئول الحكومى مع أشخاص القطاع الخاص بالبيع أو الشراء أو الإيجار أو الانتفاع أو التصرف على أى نحو مقابل السعر العادل .
ويكون التعامل مقابل سعر عادل فى تطبيق أحكام هذا القانون متى كان وفقًا للسعر وبالشروط السائدة فى السوق وقت إجراء التعامل ، دون أن يدخل فى تقديره صفة المسئول الحكومى بائعًا كان أو مشتريًا أو بأى صفة أخرى ، ودون الحصول على أية مزايا خاصة أو إضافية سواء بالنسبة للسعر أو مدة السداد أو سعر العائد أو غير ذلك من الشروط .
فإذا كان التعامل على سلع أو خدمات ليس لها سعر سائد فى السوق ، تعين على المسئول الحكومى أن يطلب من لجنة الوقاية من الفساد أن تعين خبيرًا ماليًا مستقلاً لتحديد السعر العادل ، وذلك وفقًا للإجراءات التى يحددها مجلس الوزراء .$m223$,'499f31c492c92a5937353aa90955b27b',DATE '2013-12-14'),
(13,0,$m223$المادة (13)$m223$,$m223$لا يجوز للمسئول الحكومى أن يقترض مالاً أو يحصل على تسهيل ائتمانى أو يشترى أصلاً بالتقسيط إلا وفقًا لمعدلات وشروط العائد السائدة فى السوق دون الحصول على أية مزايا إضافية ، وبشرط إخطار لجنة الوقاية من الفساد . ويسرى حكم هذه المادة بالنسبة لكل تسوية يجريها المسئول الحكومى مع جهة مانحة للائتمان .
فإذا كانت الجهة مانحة الائتمان خاضعة لرقابة أو تابعة للمسئول الحكومى ، كان تعامله معها تعارضًا مطلقًا ويحظر القيام به لو كان بالسعر العادل .$m223$,'a61f4f6c832ad434c323f0ae87b1b4e7',DATE '2013-12-14'),
(14,0,$m223$المادة (14)$m223$,$m223$مع عدم الإخلال بالنصوص المنظمة لجريمة الرشوة والتربح واستغلال النفوذ المنصوص عليها فى قانون العقوبات أو فى أى قانون آخر ، يحظر على المسئول الحكومى تلقى أو قبول هدايا أو أى أشكال أخرى من المجاملة من أى جهة سواء كانت عامة أو خاصة باستثناء ما يلى :
( أ ) الهدايا الرمزية التى يجرى العرف على تقديمها فى الأعياد والمناسبات والتى لا تجاوز قيمتها ثلاثمائة جنيه .
(ب) الهدايا التى تقدم من زائرين أو مسئولين مصريين أو أجانب فى مناسبات رسمية وفقًا للأعراف الجارية واعتبارات المجاملة ، على أن يتم تسليمها إلى جهة العمل وتسجيل ذلك بسجلات تلك الجهة .$m223$,'d5c5f04359639ccbf26482b9416ebb5a',DATE '2013-12-14'),
(15,0,$m223$المادة (15)$m223$,$m223$يحظر على المسئول الحكومى عند تركه منصبه أو وظيفته لأى سبب ، ولمدة ستة أشهر تالية ، أن يتولى منصبًا أو وظيفة فى القطاع الخاص لدى شركة أو جهة كانت تابعة أو مرتبطة بعمله السابق أو خاضعة لرقابته ، أو القيام بأعمال مهنية خاصة ترتبط بها ، أو التعامل مع الجهة التى كان يرأسها إلا بعد موافقة لجنة الوقاية من الفساد . ويحظر عليه الاستثمار فى مجالات كانت تابعة له بشكل مباشر أو تقديم الاستشارات لشركات كانت تابعة أو خاضعة لرقابة الجهة التى كان يرأسها وذلك خلال المدة المشار إليها .
ويحظر على المسئول الحكومى القيام بأى عمل مما يمكن أن يعد استغلالاً للمعلومات التى كان يتيحها منصبه أو وظيفته السابقة .$m223$,'8b54584399ed48343e1dce871c5db4ea',DATE '2013-12-14'),
(16,0,$m223$المادة (16)$m223$,$m223$مع عدم الإخلال بالأحكام المنظمة للوظيفة العامة أو الأحكام المنصوص عليها فى أى قانون آخر ، تقع مسئولية تجنب تعارض المصالح على المسئول الحكومى فيما لم يرد ذكره من أحكام .
وعلى المسئول الحكومى إخطار اللجنة فيما يمكن أن يثير الشك أو التساؤل أو الريبة مما لم يرد فى هذا القانون من حالات تعارض المصالح .$m223$,'72a797b17e919cd113c821eb9265d3db',DATE '2013-12-14'),
(17,0,$m223$المادة (17)$m223$,$m223$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى قانون العقوبات أو فى أى قانون آخر ، يعاقب بالحبس وبالغرامة التى لا تقل عن العائد الذى تحقق ولا تزيد على ضعفه أو بإحدى هاتين العقوبتين ، كل من خالف أحكام هذا القانون .
وفى جميع الأحوال يحكم برد العائد الذى تحقق بالمخالفة لأحكام هذا القانون وبالعزل من الوظيفة .$m223$,'f8272eb64e16616e612b3745e87b26c8',DATE '2013-12-14'),
(18,0,$m223$المادة (18)$m223$,$m223$يصدر مجلس الوزراء اللوائح اللازمة لتنفيذ أحكام هذا القانون بعد أخذ رأى لجنة الوقاية من الفساد .$m223$,'4a501d14079e73ce95e768b938be4952',DATE '2013-12-14'),
(19,0,$m223$المادة (19)$m223$,$m223$على جميع الخاضعين لأحكام هذا القانون توفيق أوضاعهم وفقًا لأحكامه خلال ستة أشهر من تاريخ العمل به .$m223$,'d0d7e144c5c7d6c97f612f229b81be56',DATE '2013-12-14'),
(20,0,$m223$المادة (20)$m223$,$m223$يُنشر هذا القرار بقانون فى الجريدة الرسمية ، ويعمل به بعد شهر من تاريخ نشره .
صدر برئاسة الجمهورية فى 9 المحرم سنة 1435 هـ
( الموافق 13 نوفمبر سنة 2013 م ) .
عدلى منصور$m223$,'5ed993ee3b4e229e161cf4c7cf1e59d4',DATE '2013-12-14');

