  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_nover int;
BEGIN
  IF (SELECT count(*) FROM m223_art WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[223] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m223_art) <> 21 OR (SELECT sum(char_length(body)) FROM m223_art) <> 8660 THEN
    RAISE EXCEPTION '[223] عدد الصفوف أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=106 AND law_year=2013 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%تعارض%' THEN
    RAISE EXCEPTION '[223] يوجد مستند آخر برقم 106 لسنة 2013 (%): لا يُدمج هذا القانون فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, country_code, kind, governance_scope)
    VALUES (106, 2013, $t223$القانون رقم 106 لسنة 2013 (قرار رئيس جمهورية مصر العربية بالقانون) فى شأن حظر تعارض مصالح المسئولين فى الدولة$t223$, $t223$قانون حظر تعارض المصالح 106/2013$t223$, 'other', 'in_force', NULL, DATE '2013-11-13', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m223_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
  SELECT a.id, 1, a.body, m.eff, 'active'
    FROM articles a JOIN m223_art m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m223_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 21 THEN
    RAISE EXCEPTION '[223] عدد صفوف القانون % بدل 21', v_cnt;
  END IF;
  SELECT count(*) INTO v_nover FROM articles a
   WHERE a.law_id=v_law AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id=a.id);
  IF v_nover <> 0 THEN
    RAISE EXCEPTION '[223] % صف بلا نسخة', v_nover;
  END IF;
  RAISE NOTICE '[223] قانون 106/2013: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m223$;
